public ModelMetrics TrainAndEvaluate(string dataPath)
{
    var data = _mlContext.Data.LoadFromTextFile<TicketData>(
        dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    var pipeline = _mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject))
        .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
        .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
        .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
        .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
        .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    // Cross-validate for metrics (suitable for small datasets)
    var cvResults = _mlContext.MulticlassClassification.CrossValidate(data, pipeline, numberOfFolds: 3);
    var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
    var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
    var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);

    // Train final model on all data
    _model = pipeline.Fit(data);

    var result = new ModelMetrics
    {
        MacroAccuracy = avgMacro,
        MicroAccuracy = avgMicro,
        LogLoss = avgLogLoss
    };

    _logger.LogInformation(
        "Model trained (3-fold CV) — MacroAccuracy: {MacroAccuracy:F4}, MicroAccuracy: {MicroAccuracy:F4}, LogLoss: {LogLoss:F4}",
        result.MacroAccuracy, result.MicroAccuracy, result.LogLoss);

    // Save model
    var modelPath = Path.Combine(Path.GetDirectoryName(dataPath)!, "model.zip");
    _mlContext.Model.Save(_model, data.Schema, modelPath);

    return result;
}

